const salida = [];

for (let indice = 0; indice < items.length; indice++) {
  const item = items[indice] ?? {};
  const origen = item.json ?? {};
  const binarios = item.binary ?? {};
  const propiedades = Object.keys(binarios);
  const propiedad = propiedades.includes('data') ? 'data' : (propiedades[0] ?? '');
  const archivo = propiedad ? (binarios[propiedad] ?? {}) : {};

  const mimeType = String(archivo.mimeType ?? archivo.mime ?? '').trim().toLowerCase();
  const fileName = String(archivo.fileName ?? archivo.filePath ?? '').trim().toLowerCase();
  const extension = String(archivo.fileExtension ?? '').trim().toLowerCase().replace(/^\./, '');
  const hint = String(origen.tipo_media_hint ?? '').trim().toLowerCase();

  let firmaHex = '';
  let firmaAscii = '';
  let archivoBytes = 0;
  if (propiedad) {
    try {
      const buffer = await this.helpers.getBinaryDataBuffer(indice, propiedad);
      archivoBytes = buffer.length;
      firmaHex = buffer.subarray(0, 24).toString('hex').toLowerCase();
      firmaAscii = buffer.subarray(0, 24).toString('latin1');
    } catch {
      // MIME, nombre, extensiÃ³n y pista segura de URL quedan como respaldo.
    }
  }

  const esPdf =
    firmaAscii.startsWith('%PDF-') ||
    mimeType === 'application/pdf' ||
    extension === 'pdf' ||
    fileName.endsWith('.pdf') ||
    hint === 'pdf';

  const esImagen = !esPdf && (
    firmaHex.startsWith('ffd8ff') ||
    firmaHex.startsWith('89504e470d0a1a0a') ||
    firmaAscii.startsWith('GIF8') ||
    (firmaAscii.startsWith('RIFF') && firmaAscii.includes('WEBP')) ||
    mimeType.startsWith('image/') ||
    ['png', 'jpg', 'jpeg', 'webp', 'gif', 'heic', 'heif'].includes(extension) ||
    /\.(?:png|jpe?g|webp|gif|heic|heif)$/.test(fileName) ||
    hint === 'imagen'
  );

  const extensionesAudioOpenAI = [
    'flac', 'mp3', 'mp4', 'mpeg', 'mpga', 'm4a', 'ogg', 'wav', 'webm',
  ];
  const firmaOgg = firmaAscii.startsWith('OggS');
  const firmaWav = firmaAscii.startsWith('RIFF') && firmaAscii.includes('WAVE');
  const firmaFlac = firmaAscii.startsWith('fLaC');
  const firmaMp3 =
    firmaAscii.startsWith('ID3') ||
    /^(fffb|fff3|fff2)/.test(firmaHex);
  const firmaM4a = firmaAscii.slice(4, 12).includes('ftypM4A');

  const esAudio = !esPdf && !esImagen && (
    mimeType.startsWith('audio/') ||
    extensionesAudioOpenAI.includes(extension) ||
    new RegExp('\\.(?:' + extensionesAudioOpenAI.join('|') + ')$').test(fileName) ||
    firmaOgg ||
    firmaWav ||
    firmaFlac ||
    firmaMp3 ||
    firmaM4a ||
    hint === 'audio'
  );

  let formatoAudio = '';
  if (esAudio) {
    if (firmaOgg || mimeType.includes('ogg')) formatoAudio = 'ogg';
    else if (firmaWav || mimeType.includes('wav')) formatoAudio = 'wav';
    else if (firmaFlac || mimeType.includes('flac')) formatoAudio = 'flac';
    else if (firmaMp3 || mimeType.includes('mpeg')) formatoAudio = 'mp3';
    else if (firmaM4a || mimeType.includes('mp4')) formatoAudio = 'm4a';
    else if (mimeType.includes('webm')) formatoAudio = 'webm';
    else if (extensionesAudioOpenAI.includes(extension)) formatoAudio = extension;
    else formatoAudio = 'ogg';
  }

  if (esAudio && propiedad) {
    const nombreValido = new RegExp('\\.(?:' + extensionesAudioOpenAI.join('|') + ')$', 'i').test(
      String(archivo.fileName ?? '')
    );
    if (!nombreValido) archivo.fileName = 'audio_manychat.' + formatoAudio;
    archivo.fileExtension = formatoAudio;
    if (!mimeType || mimeType === 'application/octet-stream') {
      const mimes = {
        flac: 'audio/flac', mp3: 'audio/mpeg', mp4: 'audio/mp4',
        mpeg: 'audio/mpeg', mpga: 'audio/mpeg', m4a: 'audio/mp4',
        ogg: 'audio/ogg', wav: 'audio/wav', webm: 'audio/webm',
      };
      archivo.mimeType = mimes[formatoAudio] ?? 'audio/ogg';
    }
  }

  const limiteAudioBytes = 25 * 1024 * 1024;
  const audioDentroDelLimite = esAudio && archivoBytes > 0 && archivoBytes <= limiteAudioBytes;

  salida.push({
    json: {
      ...origen,
      binary_property: propiedad,
      archivo_mime_type: String(archivo.mimeType ?? mimeType).toLowerCase(),
      archivo_nombre: String(archivo.fileName ?? fileName),
      archivo_extension: String(archivo.fileExtension ?? extension),
      archivo_bytes: archivoBytes,
      archivo_firma_detectada: firmaAscii.startsWith('%PDF-')
        ? 'PDF'
        : (firmaHex.slice(0, 24) || ''),
      es_pdf_comprobante: esPdf,
      es_imagen_comprobante: esImagen,
      es_audio: esAudio,
      es_audio_transcribible: audioDentroDelLimite,
      audio_supera_25mb: esAudio && archivoBytes > limiteAudioBytes,
      formato_audio: formatoAudio,
      archivo_descargado: Boolean(propiedad),
      tipo_archivo_detectado: esPdf
        ? 'pdf'
        : (esImagen ? 'imagen' : (esAudio ? 'audio' : 'desconocido')),
    },
    binary: binarios,
  });
}

return salida;

