function filasDesdeItems(items) {
  const filas = [];
  for (const item of items) {
    const json = item?.json;
    if (!json || typeof json !== 'object') continue;
    if (Array.isArray(json)) filas.push(...json);
    else if (Array.isArray(json.data)) filas.push(...json.data);
    else if (Object.keys(json).length) filas.push(json);
  }
  return filas.filter((fila) => fila && typeof fila === 'object' && fila.id !== undefined);
}

function booleano(valor) {
  if (typeof valor === 'boolean') return valor;
  return ['1', 'true', 'si', 'sÃ­', 'yes'].includes(String(valor ?? '').trim().toLowerCase());
}

function inicio(fila) {
  const valor = String(
    fila.jacuzzi_inicio ?? fila.masaje_inicio ?? fila.fecha_hora ?? fila.fecha_reserva ?? ''
  ).trim();
  const match = valor.match(/^(\d{4}-\d{2}-\d{2})[T\s](\d{1,2}):(\d{2})/);
  return match
    ? match[1] + 'T' + String(Number(match[2])).padStart(2, '0') + ':' + match[3]
    : '';
}

function hoyMexico() {
  const partes = new Intl.DateTimeFormat('en-US', {
    timeZone: 'America/Mexico_City',
    year: 'numeric', month: '2-digit', day: '2-digit',
  }).formatToParts(new Date());
  const valores = Object.fromEntries(partes.map((parte) => [parte.type, parte.value]));
  return valores.year + '-' + valores.month + '-' + valores.day;
}

const filas = filasDesdeItems($input.all());
const subscriberId = String(origen.subscriber_id ?? '').trim();
const hoy = hoyMexico();
// `cancelando_expirada` NO se descarta: es el estado exacto en el que queda la pre-reserva
// cuando vence la ventana de 2 h, justo cuando mÃ¡s comprobantes llegan. Antes se ignoraba y
// el bot le pedÃ­a datos al cliente teniendo el comprobante completo (caso real del 26/09/2026,
// borrador 226, transferencia Banorte de $1,500). Ahora se liga igual que `expirado_sin_pago`:
// si las citas siguen en Pabau se consulta Banxico; si ya se liberaron, el comprobante protege
// el expediente y el flujo 4.5 vuelve a crear las citas cuando el equipo aprueba el pago.
const estadosDescartados = new Set([
  'confirmado', 'expirado', 'cancelado'
]);

const candidatas = filas.filter((fila) => {
  if (String(fila.subscriber_id ?? '').trim() !== subscriberId) return false;
  if (booleano(fila.pago_recibido) || booleano(fila.reserva_confirmada)) return false;
  if (estadosDescartados.has(String(fila.estado_reserva ?? '').trim().toLowerCase())) return false;
  const cita = inicio(fila);
  return cita && cita.slice(0, 10) >= hoy;
});

const prioridadEstado = (fila) => {
  const estado = String(fila.estado_reserva ?? '').trim().toLowerCase();
  if (estado === 'pendiente_pago') return 5;
  if (estado === 'creando_retencion') return 4;
  if (estado === 'esperando_pago') return 3;
  if (estado === 'procesando_pabau') return 2;
  return 1;
};

candidatas.sort((a, b) => {
  const prioridad = prioridadEstado(b) - prioridadEstado(a);
  if (prioridad !== 0) return prioridad;
  const idA = Number(a.id);
  const idB = Number(b.id);
  if (Number.isFinite(idA) && Number.isFinite(idB) && idA !== idB) return idB - idA;
  const actualizado = (Date.parse(b.updated_at ?? b.created_at ?? 0) || 0) -
    (Date.parse(a.updated_at ?? a.created_at ?? 0) || 0);
  if (actualizado !== 0) return actualizado;
  return inicio(b).localeCompare(inicio(a));
});

const idExplicito=String(origen.reserva_draft_id||'').trim();
const exactas=idExplicito?candidatas.filter(r=>String(r.id)===idExplicito):candidatas;
// Varias pre-reservas activas: antes de darlo por ambiguo se intenta ligar el comprobante
// con seÃ±ales del propio documento (anticipo de $500 por persona y nombre de quien paga).
// Si no alcanza para identificar UNA sola, se conserva la ambigÃ¼edad y el equipo recibe aviso.
function spaNormNombre(v){return String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').replace(/\s+/g,' ').trim();}
let seleccionada=exactas.length===1?exactas[0]:null;
let asociacion_por_senal=null;
if(!seleccionada && !idExplicito && exactas.length>1){
  // La pre-reserva con la retenciÃ³n VIVA de Pabau manda: una pre-reserva vencida o ya
  // liberada (retencion_cancelada_at con valor, pabau_reservado en false) NO es candidata.
  // Son exactamente las condiciones que exige 4.4 para poder avisar por correo.
  const ESTADOS_SIN_RETENCION=new Set(['expirado','cancelado','cancelando_expirada']);
  const retencionViva=fila=>!ESTADOS_SIN_RETENCION.has(String(fila.estado_reserva??'').trim().toLowerCase())
    && !String(fila.retencion_cancelada_at??'').trim()
    && (fila.pabau_reservado===true||['true','1'].includes(String(fila.pabau_reservado??'').trim().toLowerCase()));
  const vivas=exactas.filter(retencionViva);
  const base=vivas.length?vivas:exactas;
  const montoRecibido=Number(origen.monto_pago);
  const porMonto=Number.isFinite(montoRecibido)&&montoRecibido>0
    ? base.filter(r=>{const p=Number(r.numero_personas??r.personas);return Number.isInteger(p)&&p>0&&p*500===montoRecibido;})
    : [];
  const textosPago=[origen.nombre_ordenante,origen.concepto_pago].map(spaNormNombre).filter(t=>t.length>=4);
  const porNombre=textosPago.length
    ? base.filter(r=>{const n=spaNormNombre(r.nombre);return n.length>=4&&textosPago.some(t=>t===n||t.includes(n)||n.includes(t));})
    : [];
  const mismo=(a,b)=>String(a.id)===String(b.id);
  // El nombre de quien paga solo distingue cuando coincide con UNA sola pre-reserva. Si
  // coincide con todas (el cliente es el mismo en sus pre-reservas) no aporta nada, asÃ­ que
  // el monto del anticipo decide. Si las seÃ±ales se contradicen, no se liga: va a aviso.
  const nombreDistingue=porNombre.length===1;
  const nombreNeutro=porNombre.length!==1;
  const compatible=r=>nombreNeutro||mismo(r,porNombre[0]);
  if(porMonto.length===1&&compatible(porMonto[0])){seleccionada=porMonto[0];asociacion_por_senal=nombreDistingue?'MONTO_Y_ORDENANTE':'MONTO_ANTICIPO';}
  else if(!porMonto.length&&nombreDistingue){seleccionada=porNombre[0];asociacion_por_senal='ORDENANTE';}
  else if(porMonto.length>1&&nombreDistingue&&porMonto.some(r=>mismo(r,porNombre[0]))){seleccionada=porNombre[0];asociacion_por_senal='ORDENANTE_CON_MONTO_COMPATIBLE';}
  // Si entre varias candidatas solo UNA conserva la retenciÃ³n viva, es esa: las demÃ¡s ya
  // se vencieron o liberaron y no pueden quedarse con el pago.
  else if(vivas.length===1){seleccionada=vivas[0];asociacion_por_senal='UNICA_CON_RETENCION_VIVA';}
}
const personas = seleccionada ? Number(seleccionada.numero_personas ?? seleccionada.personas) : null;
const montoEsperado = Number.isFinite(personas) && personas > 0 ? personas * 500 : null;

return [{
